START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121110612_AddBarCloseAtm') THEN
    CREATE TABLE adaptive_bar_close_atm (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "SessionId" bigint NOT NULL,
        "BarSeq" integer NOT NULL,
        "Version" character varying(32) NOT NULL,
        "AtmStrike" double precision,
        "Spot" double precision,
        "UnavailableReason" character varying(256),
        CONSTRAINT "PK_adaptive_bar_close_atm" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_adaptive_bar_close_atm_adaptive_sessions_SessionId" FOREIGN KEY ("SessionId") REFERENCES adaptive_sessions ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121110612_AddBarCloseAtm') THEN
    CREATE UNIQUE INDEX "IX_adaptive_bar_close_atm_SessionId_BarSeq_Version" ON adaptive_bar_close_atm ("SessionId", "BarSeq", "Version");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261121110612_AddBarCloseAtm') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261121110612_AddBarCloseAtm', '10.0.11');
    END IF;
END $EF$;
COMMIT;

